### Packrat Parsing for Statements

Consider the following PEG for assignment statements and procedure calls; it is a fragment of the P0 grammar:

    statement ←
        ident selector ':=' ident /
        ident (',' ident)* ':=' ident (',' ident)* /
        ident (',' ident)* '←' ident '(' ident ')'
    selector ← ('[' ident ']' / '.' ident)*
    ident  ← 'a' / ... / 'z'

Implement the parser as a backtracking parser, following the rules from the course notes. You may use the commented version of method `literal`.

```python
class StatementBacktrack:
  src: str

  def literal(self, k: int, a: str):
    if self.src.startswith(a, k):
      return k + len(a)
    # if self.src.startswith(a, k): print('match', a, 'at', k); return k + len(a)
    # else: print('fail', a, 'at', k); return None

  def ident(self, k):
    if k < len(self.src) and 'a' <= self.src[k] <= 'z':
      return k + 1

  def selector(self, k):
    while True:
      k2 = self.literal(k, '[')
      if k2 is not None:
        k3 = self.ident(k2)
        if k3 is None:
          break
        k4 = self.literal(k3, ']')
        if k4 is None:
          break
        k = k4
        continue
      k2 = self.literal(k, '.')
      if k2 is not None:
        k3 = self.ident(k2)
        if k3 is None:
          break
        k = k3
        continue
      break
    return k

def statement(self, k):
    k1 = self.ident(k)
    if k1 is not None:
      k2 = self.selector(k1)
      if k2 is not None:
        k3 = self.literal(k2, ':=')
        if k3 is not None:
          k4 = self.ident(k3)
          if k4 is not None:
            return k4
    k1 = self.ident(k)
    if k1 is not None:
      while True:
        k2 = self.literal(k1, ',')
        if k2 is None:
          break
        k3 = self.ident(k2)
        if k3 is None:
          break
        k1 = k3
      k2 = self.literal(k1, ':=')
      if k2 is not None:
        k3 = self.ident(k2)
        if k3 is not None:
          k4 = k3
          while True:
            k5 = self.literal(k4, ',')
            if k5 is None:
              break
            k6 = self.ident(k5)
            if k6 is None:
              break
            k4 = k6
          return k4
    k1 = self.ident(k)
    if k1 is not None:
      while True:
        k2 = self.literal(k1, ',')
        if k2 is None:
          break
        k3 = self.ident(k2)
        if k3 is None:
          break
        k1 = k3
      k2 = self.literal(k1, '←')
      if k2 is not None:
        k3 = self.ident(k2)
        if k3 is not None:
          k4 = self.literal(k3, '(')
          if k4 is not None:
            k5 = self.ident(k4)
            if k5 is not None:
              k6 = self.literal(k5, ')')
              if k6 is not None:
                return k6
    return None

  def parse(self, s: str):
    self.src = s
    return self.statement(0) == len(s)
```

